// Handle control commands: pause, resume, stop, repeat
const action = $json.parameters.control_action || $json.original_text.toLowerCase();
let response = '';

if (action.includes('pause') || action.includes('wait') || action.includes('stop')) {
  response = 'Pausing now.';
} else if (action.includes('resume') || action.includes('continue') || action.includes('start')) {
  response = 'Resuming reading.';
} else if (action.includes('repeat') || action.includes('again') || action.includes('go back')) {
  response = 'Repeating from where I left off.';
} else {
  response = 'Got it.';
}

return [{ json: { response_text: response, action: action } }];

// Collect response text from whichever branch ran
// Try each possible LLM node output
let responseText = 'Sorry, I did not understand that. Please try again.';

try {
  // Each branch outputs from a different node — check which has data
  const navigateOut = $('Claude — Navigate Guidance').all();
  const findBookOut = $('Claude — Find Book Response').all();
  const readAloudOut = $('Claude — Clean and Read Text').all();
  const qaOut = $('Claude — Answer Question').all();
  const controlOut = $('Control Command Handler').all();

  if (navigateOut.length > 0) {
    responseText = navigateOut[0].json.content[0].text;
  } else if (findBookOut.length > 0) {
    responseText = findBookOut[0].json.content[0].text;
  } else if (readAloudOut.length > 0) {
    responseText = readAloudOut[0].json.content[0].text;
  } else if (qaOut.length > 0) {
    responseText = qaOut[0].json.content[0].text;
  } else if (controlOut.length > 0) {
    responseText = controlOut[0].json.response_text;
  }
} catch(e) {
  responseText = 'Something went wrong. Please try again.';
}

return [{ json: { response_text: responseText } }];

